nextflow_process {

    name "Test Process CUSTOM_RSEMMERGECOUNTS"
    script "../main.nf"
    process "CUSTOM_RSEMMERGECOUNTS"

    tag "modules"
    tag "modules_nfcore"
    tag "custom"
    tag "custom/rsemmergecounts"

    test("saccharomyces_cerevisiae") {
        def rsem
        setup {
            // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
            def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'
            rsem = extract(modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/rsem_results.tar.gz')
        }

        when {
            process {
                """
                input[0] = [ [ id: 'rsem_merged' ], files('${rsem}/*/*.genes.results') ]
                input[1] = files('${rsem}/*/*.isoforms.results')
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(
                    process.out.counts_gene,
                    process.out.tpm_gene,
                    process.out.counts_transcript,
                    process.out.tpm_transcript,
                    process.out.genes_long,
                    process.out.isoforms_long,
                    process.out.findAll { key, val -> key.startsWith('versions') }
                ).match() }
            )
        }
    }

    test("saccharomyces_cerevisiae - stub") {

        options "-stub"

        when {
            process {
                """
                input[0] = channel.of(
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true)
                ).collect().map { files -> [ [ id: 'rsem_merged' ], files ] }
                input[1] = channel.of(
                    file(params.modules_testdata_base_path + 'genomics/eukaryotes/saccharomyces_cerevisiae/genome_gfp.gtf', checkIfExists: true)
                ).collect()
                """
            }
        }

        then {
            assertAll(
                { assert process.success },
                { assert snapshot(process.out).match() }
            )
        }
    }
}
